<script>
(()=>{const b=document.getElementById('sk1022SyncBtn');if(!b)return;b.addEventListener('click',()=>{const vis=e=>{const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&r.width>0&&r.height>0};const c=[...document.querySelectorAll('.admin-sidebar,.sidebar,#sidebar,aside,[data-admin-sidebar],[data-sidebar],nav')].filter(vis).map(e=>[e,e.querySelectorAll('a[href^="/admin/"],a[href*="/admin/"]').length]).filter(x=>x[1]>=3).sort((a,b)=>b[1]-a[1]);const side=c[0]?.[0];if(!side){alert('Admin sidebar could not be detected.');return}const seen=new Set(),rows=[];for(const a of side.querySelectorAll('a[href]')){if(a.closest('#sk-sidebar-registry-v1022'))continue;let u;try{const x=new URL(a.href,location.origin);if(!x.pathname.startsWith('/admin/'))continue;u=x.pathname}catch(e){continue}if(seen.has(u))continue;const label=(a.textContent||'').replace(/\s+/g,' ').trim();if(!label||label.length>160)continue;seen.add(u);rows.push({url:u,label})}document.getElementById('sk1022NativeJson').value=JSON.stringify(rows);document.getElementById('sk1022SyncForm').submit()})})();
</script>
